  (299, 35, 2, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'requisitos', '{"titulo":"Necesitas el código de SERTRACEN","lineas":["Antes de iniciar, SERTRACEN te envía por correo un código de autorización de tu documento. Con ese código el VMT hace la verificación"]}'::jsonb, false),
