  (301, 35, 4, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'aviso', '{"titulo":"Nota legal","lineas":["Si envías información falsa, cometes el delito de estafa informática (artículo 10 de la Ley Especial contra los Delitos Informáticos y Conexos) y el trámite se elimina automáticamente","La Dirección General de Transporte puede dar aviso a la Fiscalía General de la República para que determine los efectos legales"]}'::jsonb, false),
