  (306, 37, 1, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'info', '{"titulo":"Asesoría","lineas":["Si tienes dudas sobre el trámite, escribe al VMT por WhatsApp al 7124-7428 (solo mensajes) o al correo vmtdigital@mop.gob.sv"]}'::jsonb, false),
  (307, 37, 2, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'requisitos', '{"titulo":"Documentos del representante del menor","lineas":["## Obligatorios","- NIT del menor","- Boleta de los exámenes de manejo aprobados","- Fianza moral: documento privado ante notario en el que te comprometes a responder por los daños a terceros que ocasione el menor","- Partida de nacimiento del menor, de no más de 6 meses. La edad mínima para pedir la licencia es 15 años","- Fianza bancaria de $571.43 por daños a terceros, vigente hasta que el menor cumpla 18 años","- Si solo está presente uno de los padres: declaración jurada original que explique la ausencia del otro. El trámite lo hace el padre o la madre presente","- Si faltan los dos padres: certificación notarial de la resolución judicial que te faculta para representar al menor","## Adicional","- Si ayudas al representante del menor a usar SIMPLE: el poder con el que lo representas","Los documentos se piden a medida que avanzas en el trámite"]}'::jsonb, false),
  (308, 38, 1, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'info', '{"titulo":"Asesoría","lineas":["Si tienes dudas sobre el trámite, escribe al VMT por WhatsApp al 7124-7428 (solo mensajes) o al correo vmtdigital@mop.gob.sv"]}'::jsonb, false),
