  (457, 68, 1, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'info', '{"titulo":"¡Hola!","lineas":["Este trámite que estás a punto de iniciar puede generar un costo variable según el documento solicitado; asegúrate de tener una tarjeta de crédito o débito para realizar el pago","El valor generado únicamente constituye un arancel por la prestación del servicio, por lo que no existe devolución del mismo"]}'::jsonb, false),
  (458, 68, 2, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'aviso', '{"titulo":"¡Nota importante!","lineas":["Para realizar el trámite, ten en cuenta los siguientes términos:","- El trámite solicitado consiste en la búsqueda y validación de la información proporcionada. Una vez ingresado y procesado, no será posible la devolución del costo del servicio, independientemente del resultado","- Si la información ingresada es incorrecta o inexacta, el documento será desfavorable y no procede la devolución","- Eres responsable del uso de tarjetas de crédito o débito para el pago del trámite","- La emisión del documento se basará en la información que haya sido registrada por la alcaldía municipal","- Eres responsable de la información que ingresas en la etapa de identificación del trámite","- El plazo de respuesta es de 24 horas hábiles para el servicio de certificación de partidas"]}'::jsonb, false),
  (459, 68, 3, 'opciones', 'acepta_terminos', '¿Aceptas los términos antes mencionados?', NULL, NULL, NULL, true, false, false, NULL, NULL, NULL, false),
  (460, 69, 1, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'info', '{"titulo":"¡Hola!","lineas":["Este trámite que estás a punto de iniciar genera un costo de hasta $5.00 por el servicio brindado; asegúrate de tener una tarjeta de crédito o débito para realizar el pago","Este valor únicamente constituye un arancel por la prestación del servicio, sin que esto signifique la emisión de un documento favorable. En caso de que el resultado no sea favorable, no hay devolución"]}'::jsonb, false),
  (461, 69, 2, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'aviso', '{"titulo":"Aceptación de términos","lineas":["Para realizar el trámite, estoy consciente y tengo en cuenta los siguientes términos:","- La información que ingreso en la etapa de identificación del trámite es mi responsabilidad","- El trámite solicitado consiste en la búsqueda y validación de la información proporcionada. Una vez ingresado y procesado, no será posible la devolución del costo del servicio independientemente del resultado","- Si la información es incorrecta o inexacta, el documento será desfavorable y no procederá la devolución","- Es mi responsabilidad el uso de tarjetas de crédito o débito para el pago del trámite","Asimismo declaro bajo juramento: I) Que conozco los términos y requisitos previos establecidos y en caso de estar mintiendo en la información declarada o entregando documentos alterados o falsificados, estaré incurriendo en el delito de estafa informática establecido en el artículo 10 de la Ley Especial contra los Delitos Informáticos y Conexos"]}'::jsonb, false),
