  (533, 83, 1, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'aviso', '{"titulo":"Declaración jurada","lineas":["Declaro bajo juramento que la información del formulario y de los documentos anexos es verdadera y cumple los requisitos legales. Asumo la responsabilidad administrativa, civil y penal por cualquier falsedad o alteración","Acepto recibir notificaciones por correo electrónico y por SIMPLE.SV. Si se comprueban irregularidades, la autoridad puede anular de oficio el trámite y aplicar las sanciones que correspondan"]}'::jsonb, false),
  (534, 83, 2, 'nota', NULL, NULL, NULL, NULL, NULL, false, false, false, NULL, 'aviso', '{"titulo":"Cláusula antisoborno","lineas":["Está prohibido ofrecer, prometer, pedir o entregar, directa o indirectamente, dinero, regalos, beneficios indebidos, favores u otro incentivo a servidores, empleados o funcionarios del ISBM, o a terceros relacionados, para acelerar, cambiar o influir en el resultado del trámite","El ISBM tiene un Sistema de Gestión Antisoborno según la norma ISO 37001. Cualquier intento de soborno o práctica corrupta puede llevar al rechazo, la suspensión o la cancelación del trámite, además de las sanciones administrativas, civiles o penales","Usar la plataforma implica aceptar este compromiso y actuar con integridad, transparencia y apego a la legalidad"]}'::jsonb, false),
